  if($("#cutModeHint"))$("#cutModeHint").textContent=quick?"Geführt und übersichtlich: Format wählen, Clip schneiden, optional Ton ergänzen und exportieren.":"Alle Werkzeuge sichtbar: Mixer, Mehrspur, Übergänge, Encoder, Keyframes, Kurven und Feineinstellungen.";
