// Save state is compared against the rendered, server-confirmed editor. Playback position is
// intentionally excluded: a running preview is not an unsaved edit.
let savedCutProjectSnapshot=null;
let savedCutClipsSnapshot=null;
let cutSaving=false;
function cutProjectSnapshot(){
  if(!state.project)return null;
  const payload=projectPayload();
  delete payload.export_preset.audition_playhead_ms;
  return JSON.stringify(payload);
}
function cutClipsSnapshot(){
  if(!state.project)return null;
  return JSON.stringify([...document.querySelectorAll("#cutClipList [data-clip]")].map(row=>({
    id:row.dataset.clip,
    fields:[...row.querySelectorAll("[data-field], [data-kf]")].map((el,index)=>[index,el.dataset.field||el.dataset.kf,el.value])
  })));
}
function rememberCutSaved({project=true,clips=true}={}){
  if(project)savedCutProjectSnapshot=cutProjectSnapshot();
  if(clips)savedCutClipsSnapshot=cutClipsSnapshot();
  updateCutSaveState();
}
function cutHasUnsavedChanges(){
  return Boolean(state.project)&&(savedCutProjectSnapshot!==cutProjectSnapshot()||savedCutClipsSnapshot!==cutClipsSnapshot());
}
function updateCutSaveState(){
  const status=$("#cutSaveState");if(!status)return;
  const pending=cutHasUnsavedChanges();
  status.hidden=!pending&&!cutSaving;
  status.textContent=cutSaving?"Wird gespeichert …":"Änderungen nicht gespeichert";
}
function confirmCutDiscard(){
  return !cutHasUnsavedChanges()||window.confirm("Ungespeicherte Änderungen an Projekt oder Clips verwerfen?");
}
function render(){renderProjects();renderEditor();renderJobs();updateCutGuide()}

async function load(){const [d,j]=await Promise.all([CFS.json("/api/creator/cut-studio/projects"),CFS.json("/api/creator/cut-studio/jobs")]);state.projects=d.projects||[];state.limits={...state.limits,...(d.limits||{}),max_pending_jobs:Number(j.limits?.max_pending_jobs||0)};state.jobs=j.jobs||[];renderProjects();renderJobs();const wanted=new URLSearchParams(location.search).get("project");if(wanted&&!state.project){const found=state.projects.find(p=>p.id===wanted);if(found)await openProject(found.id)}}
async function openProject(id,{skipConfirm=false,force=false}={}){
  if(state.project?.id===id&&!force)return false;
  if(!skipConfirm&&!confirmCutDiscard())return false;
  // Keep the current draft in place on network/API failures.
  const d=await CFS.json(`/api/creator/cut-studio/projects/${encodeURIComponent(id)}`);
  document.dispatchEvent(new CustomEvent("cfs:cut-project-open",{detail:{id}}));
  zeroCrossInspection=null;zeroCrossBusy=false;
  for(const key of ["cutAuditionPlayhead","cutAuditionA","cutAuditionB"]){const el=$(`#${key}`);if(el)delete el.dataset.ready}
  auditionRuntime={active:false,state:"idle",session_id:"",position_ms:0,start_ms:0,end_ms:0,sampled_at_ms:0,updated_at:null,fresh:false};auditionSessionRequested=false;
  state.project=d.project;state.clips=d.clips||[];render();rememberCutSaved();loadAuditionRuntime().catch(()=>{});
  return true;
}
// Collect editor values without changing the server; the R158 save endpoint commits all rows.
function readVisibleClips(){
  window.CFSCutPreview?.validateClips();
  const clipsById=new Map(state.clips.map(clip=>[String(clip.id),clip]));
  return [...$("#cutClipList").querySelectorAll("[data-clip]")].map(row=>{
    const id=String(row.dataset.clip||"");
    const previous=clipsById.get(id);
    if(!previous||!previous.updated_at)throw new Error("Clip-Version fehlt. Bitte Projekt neu öffnen.");
    const get=f=>row.querySelector(`[data-field="${f}"]`)?.value||"";
    return {
      id,base_updated_at:previous.updated_at,
      label:get("label"),in_ms:Math.round(Number(get("in_s")||0)*1000),out_ms:Math.round(Number(get("out_s")||0)*1000),
      caption:get("caption"),selected:get("selected")==="true",caption_enabled:get("caption_enabled")==="true",
      caption_position:get("caption_position"),caption_style:get("caption_style"),caption_size:Number(get("caption_size")||52),
      audio_gain_db:Number(get("audio_gain_db")||0),audio_fade_in_ms:Number(get("audio_fade_in_ms")||0),audio_fade_out_ms:Number(get("audio_fade_out_ms")||0),
      keyframe_enabled:get("keyframe_enabled")==="true",keyframe_zoom_start:Number(get("keyframe_zoom_start")||1),keyframe_zoom_end:Number(get("keyframe_zoom_end")||1),
      keyframe_pan_x_start:Number(get("keyframe_pan_x_start")||0),keyframe_pan_x_end:Number(get("keyframe_pan_x_end")||0),
      keyframe_pan_y_start:Number(get("keyframe_pan_y_start")||0),keyframe_pan_y_end:Number(get("keyframe_pan_y_end")||0),
      keyframe_easing:get("keyframe_easing")||"linear",visual_keyframes:readVisualPoints(row)
    };
  });
}
async function saveProject({quiet=false}={}){
  const d=await CFS.json(`/api/creator/cut-studio/projects/${encodeURIComponent(state.project.id)}`,{method:"PUT",body:JSON.stringify({...projectPayload(),base_updated_at:state.project.updated_at})});
  state.project=d.project;
  if(!quiet){await load();render();rememberCutSaved();toast("Cut-Projekt gespeichert.")}
  else rememberCutSaved({clips:false});
  return state.project;
}
// The main Save action must persist both project settings AND edited clip rows.
async function saveAllCutChanges({quiet=false}={}){
  if(!state.project)throw new Error("Kein Cut-Projekt geöffnet.");
  if(cutSaving)throw new Error("Speichervorgang läuft bereits.");
  cutSaving=true;updateCutSaveState();
  try{
    const clips=readVisibleClips();
    const project={...projectPayload(),base_updated_at:state.project.updated_at};
    const data=await CFS.json(`/api/creator/cut-studio/projects/${encodeURIComponent(state.project.id)}/save`,{
      method:"PUT",body:JSON.stringify({project,clips})
    });
    // Apply server state only after a successful COMMIT; failed saves keep editable rows intact.
    state.project=data.project;state.clips=data.clips||[];
    render();rememberCutSaved();
    // Refresh the sidebar opportunistically. A list refresh failure must not undo a committed save.
    await load().catch(()=>{});
    if(!quiet)toast("Projekt und Clips gemeinsam gespeichert.");
    return data;
  }finally{cutSaving=false;updateCutSaveState()}
}
// Structural changes redraw the clip list. Persist every pending editor field first,
// so adding, reordering and deleting never silently discard another unsaved row.
let cutClipStructureBusy=false;
async function mutateCutClipStructure(action){
  if(cutSaving||cutClipStructureBusy)throw new Error("Bitte den laufenden Speichervorgang abwarten.");
  cutClipStructureBusy=true;
  try{
    if(cutHasUnsavedChanges())await saveAllCutChanges({quiet:true});
    const result=await action();
    rememberCutSaved({project:false});
    return result;
  }finally{cutClipStructureBusy=false;updateCutSaveState()}
}
